actions.script:
const input = {}
for (const name of ['publicationId', 'formId', 'expectedRevision', 'accessEnumId', 'repeatEnumId', 'siteId', 'fromDate',
        'thruDate', 'description', 'titleText', 'introText', 'completionMessage', 'contextEntityName', 'contextId'])
    if (context.containsKey(name) && context[name] !== undefined) input[name] = context[name]
const out = ec.resource.script('component://mr-mantle/service/mantle/party/FormPublication.js').execute('storePublication', input)
publicationId = out.publicationId
created = out.created
